import { g as getModelInfo } from "../../../../../../chunks/crud.js";
import { l as loadDetail } from "../../../../../../chunks/load.js";
import { B as BASE_API_URL } from "../../../../../../chunks/constants.js";
import "@sveltejs/kit";
import { n as nestedDeleteFormAction } from "../../../../../../chunks/actions.js";
const load = async (event) => {
  const detailData = await loadDetail({
    event,
    model: getModelInfo("quantitative-risk-hypotheses"),
    id: event.params.id
  });
  const lecData = await event.fetch(
    `${BASE_API_URL}/crq/quantitative-risk-hypotheses/${event.params.id}/lec/?_t=${Date.now()}`,
    {
      cache: "no-cache",
      headers: {
        "Cache-Control": "no-cache"
      }
    }
  ).then((res) => res.json());
  return {
    ...detailData,
    lec: lecData
  };
};
const actions = {
  delete: async (event) => {
    console.log("delete");
    return nestedDeleteFormAction({ event });
  },
  runSimulation: async (event) => {
    const endpoint = `${BASE_API_URL}/crq/quantitative-risk-hypotheses/${event.params.id}/run-simulation/`;
    const res = await event.fetch(endpoint, {
      method: "GET"
    });
    if (!res.ok) {
      const response = await res.json();
      console.error(response);
      return {
        error: true,
        message: response
      };
    }
    await res.json();
    return {
      success: true,
      message: { simulationComplete: true }
    };
  }
};
export {
  actions,
  load
};
